			return fmt.Errorf("dit: %s tile %dx%d does not divide [%d %d]", r, v.bm, v.bn, g.tokPad, n)
		}
		pc := base
		pc.InOff, pc.OutOff, pc.BOff = aOff, cOff, g.bOff[r]

