		pc.Aux1 = uint32(g.tokPad)
		pc.Eps = math.Float32bits(float32(g.qkEps))
		pc.Scale = math.Float32bits(scale)
		add("qkpack", kind, groups(g.tokPad, coopMatTile), uint32(g.heads), pc)
	}

