	// projection, with the 1+x and tanh already applied.
	pcMod := base
	pcMod.InOff, pcMod.OutOff, pcMod.WOff, pcMod.Aux0 = g.aAdaIn, g.aMod, g.wAdaLN, g.wAdaLNBias
	pcMod.GemmN, pcMod.GemmK = uint32(4*g.dim), uint32(g.adaIn)
