// selection is the block indices to run: sel, or every block in order when
// sel is nil.
func (g *GPUStack) selection(sel []int) ([]int, error) {
	if sel == nil {
		sel = make([]int, len(g.w))
		for i := range sel {
			sel[i] = i
		}
		return sel, nil
	}
	for _, i := range sel {
