func (g *GPUStack) Banks() (bytes []int, byBlock []int) {
	for _, b := range g.banks {
		bytes = append(bytes, b.Size())
	}
	byBlock = make([]int, len(g.w))
	for i, w := range g.w {
		byBlock[i] = w.bank
	}
	return bytes, byBlock
